async function simulate(kind){if(lab.world.operations.game.mode!=='free'){showEvent('ENGINEERING SESSION','Use challenge or campaign incidents in this mode.');return {status:'mode-restricted'};}if(lab.lan.connected){showEvent('CO-OP MODE','Use the shared port and VLAN controls in the field terminal.');return {status:'co-op'};}if(state.pending){showEvent('RECOVERY IN PROGRESS','Wait for the current transition or restore all.');return {status:'busy'};}if(state[kind]){showEvent('FAULT ALREADY ACTIVE','Restore all to run this simulation again.');return {status:'already-active'};}state[kind]=true;state.pending=true;refreshFaults();const titles={link:'LINK FAILURE // CORE-A → TOR-02',controller:'CONTROLLER A // OFFLINE',san:'PATH A // UNAVAILABLE',site:'PRIMARY SITE // UNAVAILABLE'};showEvent(titles[kind],kind==='site'?'DR ACTIVATION IN PROGRESS · Accelerated simulation':'RECALCULATING · FINDING ALTERNATE PATH',10000);return new Promise(resolve=>{const timer=setTimeout(()=>{state.pending=false;refreshFaults();showEvent(kind==='site'?'SERVICES RESTORED // DR ACTIVE':'PATH RECALCULATED',kind==='link'?'FAILOVER 43 ms · PACKET LOSS 0 · SERVICE HEALTHY':kind==='controller'?'CONTROLLER B ACTIVE · MULTIPATH OPTIMIZED · APPLICATIONS UNAFFECTED':kind==='san'?'PATH B ACTIVE / OPTIMIZED · I/O RESTORED':'SIMULATED RTO 00:00:47 · DR SERVICES HEALTHY',7500);resolve({status:'complete',fault:kind});},kind==='site'?3200:1250);simulationTimers.push({timer,resolve});});}
function restoreAll(){if(lab.world.operations.game.mode!=='free'){showEvent('ENGINEERING SESSION','Use the campaign checkpoint or retry a challenge.');return {status:'mode-restricted'};}if(lab.lan.connected){showEvent('CO-OP MODE','Use shared device configuration or reset cabling in the workbench.');return {status:'co-op'};}for(const t of simulationTimers){clearTimeout(t.timer);t.resolve({status:'cancelled'})}simulationTimers=[];Object.assign(state,{link:false,controller:false,san:false,site:false,pending:false});refreshFaults();showEvent('ALL SYSTEMS RESTORED','REDUNDANCY RESTORED · ALL PATHS AVAILABLE');return {status:'restored'};}
